const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let scene=0,table='04',cart=[],order=null,menuCategory='Coffee',tourTimer=null,orderTimer=null,tourView='cafe',audioContext=null,ambient=null,soundOn=false;
const products=[{name:'Iced oat latte',note:'Smooth. A little nutty.',price:180,icon:'🥛',category:'Coffee'},{name:'Cappuccino',note:'Your daily little ritual.',price:160,icon:'☕',category:'Coffee'},{name:'Cold brew',note:'Slow brewed. Big mood.',price:190,icon:'🧊',category:'Coffee'},{name:'Butter croissant',note:'Golden, flaky happiness.',price:140,icon:'🥐',category:'Bites'},{name:'Avocado toast',note:'Fresh, green, feel-good.',price:240,icon:'🥑',category:'Bites'},{name:'Chocolate cookie',note:'A warm little yes.',price:90,icon:'🍪',category:'Bites'}];
const scenes=[['Good things start<br>at your table.','Pick a table. Make yourself at home.'],['A menu that’s<br>always in season.','Fresh picks. Beautifully simple ordering.'],['Less shouting.<br>More sizzling.','Straight from the table to the kitchen.'],['Feel the place.<br>Before you visit.','Look around. Find your favourite corner.'],['Every little detail.<br>One clear picture.','Tables, orders and happy moments. Together.']];
const currency=n=>'₹'+n.toLocaleString('en-IN');
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function tables(){const positions=[[345,349],[287,442],[589,481]];$('#tables').innerHTML=positions.map(([x,y],i)=>`<g transform="translate(${x} ${y})"><ellipse cy="49" rx="69" ry="25" fill="#67533b" opacity=".15"/><g fill="#3e5641"><path d="M-75-10q-18-25-33-7v42q18 18 33 3Z"/><path d="M66-2q25-22 36 0v40q-16 15-36 1Z"/></g><g stroke="#354c37" stroke-width="5"><path d="M-101 23v29m22-20v30M73 30v28m24-27v15"/></g><path d="M-5 0v52m-29 8 29-12 33 14" fill="none" stroke="#4b4c36" stroke-width="8"/><ellipse cy="0" rx="68" ry="35" fill="#92734a"/><ellipse cy="-7" rx="68" ry="35" fill="#d6b481"/><ellipse cy="-10" rx="63" ry="29" fill="#dfbf90"/><ellipse cx="-29" cy="-12" rx="13" ry="7" fill="#eeead5"/><path d="M-37-19v8q8 8 16 0v-8" fill="#f9f3df"/><ellipse cx="-29" cy="-19" rx="8" ry="4" fill="#83664b"/><path d="M23-5l18-9 14 6-19 10Z" fill="#f6eed6"/><path d="M29-6l10-5 8 3-11 6Z" fill="#3c4734"/><path d="M-2-26v-11" stroke="#526e42" stroke-width="3"/><ellipse cx="-2" cy="-37" rx="7" ry="5" fill="#607d4a"/><path d="M-8-27l3 13h7l3-13Z" fill="#ad7049"/></g>`).join('')}
function setScene(n){scene=n;$$('[data-scene]').forEach((b,i)=>b.setAttribute('aria-selected',String(i===n)));$('#scene-number').textContent=`0${n+1} / 05`;$('#scene-title').innerHTML=scenes[n][0];$('#scene-caption').textContent=scenes[n][1];$('#cafe').classList.toggle('kitchen-view',n===2);$('#cafe').classList.toggle('tour-view',n===3);$('#cafe').classList.toggle('routing',n===2||!!order);render();}
function phone(html){$('#phone-content').innerHTML=html;$('#phone-content').classList.remove('reveal');void $('#phone-content').offsetWidth;$('#phone-content').classList.add('reveal')}
function render(){if(scene===0)renderScan();if(scene===1)renderMenu();if(scene===2)renderKitchen();if(scene===3)renderTour();if(scene===4)renderDashboard();$('#table-label').textContent=scene===2?'KITCHEN':scene===4?'MANAGER':`TABLE ${table}`;$$('[data-table]').forEach(b=>b.classList.toggle('selected',b.dataset.table===table))}
function qr(){let cells='';for(let y=0;y<21;y++)for(let x=0;x<21;x++){let finder=false,black=false;for(const [a,b]of [[0,0],[14,0],[0,14]])if(x>=a&&x<a+7&&y>=b&&y<b+7){finder=true;const dx=x-a,dy=y-b;black=dx===0||dx===6||dy===0||dy===6||(dx>=2&&dx<=4&&dy>=2&&dy<=4)}if(black||(!finder&&((x*7+y*13+x*y)%9<4)))cells+=`<rect x="${x}" y="${y}" width="1" height="1"/>`}return `<svg viewBox="-1 -1 23 23" aria-label="Decorative demo QR code" fill="#2c3926">${cells}</svg>`}
function renderScan(){phone(`<div class="tiny-label">A SEAT. A SCAN. A SMILE.</div><h3>Hey, good company.</h3><p>Your table. Your favourites. Your time.</p><div class="qr-box">${qr()}</div><div class="scan-caption">Table ${table} is ready for you.</div><button class="primary" data-action="scan">Try the scan <span>↗</span></button><div class="phone-badge">⌁ No app. Just an appetite.</div><div class="phone-badge">Illustrative QR · Tap to simulate</div>`)}
function renderMenu(){phone(`<div class="tiny-label">MADE FOR YOUR KIND OF DAY</div><h3>A little something<br>you’ll love.</h3><div class="menu-tabs">${['Coffee','Bites'].map(c=>`<button data-category="${c}" class="${menuCategory===c?'active':''}">${c==='Coffee'?'☕':'🥐'} ${c}</button>`).join('')}</div>${products.map((p,i)=>p.category===menuCategory?`<div class="food-row"><div class="food-icon">${p.icon}</div><div class="food-info"><b>${p.name}</b><small>${p.note}</small><strong>${currency(p.price)}</strong></div><button class="add-item" data-add="${i}" aria-label="Add ${p.name}">${cart.filter(v=>v===i).length||'+'}</button></div>`:'').join('')}<div class="menu-note">✳ Freshly made · Prices shown in INR</div><button class="primary menu-bottom" data-action="cart">${cart.length?`View order (${cart.length})`:'Pick your favourites'} <span>${cart.length?currency(cart.reduce((a,i)=>a+products[i].price,0)):'+'}</span></button>`)}
function renderCart(){if(!cart.length){notify('Add something delicious to begin.');return}const total=cart.reduce((a,i)=>a+products[i].price,0);phone(`<div class="tiny-label">YOUR LITTLE MOMENT</div><h3>Looking good.</h3><p>Sending to table ${table}.</p>${[...new Set(cart)].map(i=>`<div class="cart-row"><span>${cart.filter(v=>v===i).length} × ${products[i].name}</span><button style="background:transparent;font-size:11px" data-remove="${i}" aria-label="Remove one ${products[i].name}">−</button></div>`).join('')}<div class="cart-total"><span>Total</span><span>${currency(total)}</span></div><label class="pay-option"><input name="payment" type="radio" value="counter" checked> Pay at the counter</label><label class="pay-option"><input name="payment" type="radio" value="online"> Try online payment</label><button class="primary" data-action="order">Send to the kitchen <span>↗</span></button><button class="secondary" data-action="back-menu">← Back to menu</button><div class="phone-badge">Demo only · No money will be charged</div>`)}
function placeOrder(){const online=$('input[name=payment]:checked')?.value==='online';order={items:[...cart],table,status:'received',total:cart.reduce((a,i)=>a+products[i].price,0),paid:online};cart=[];$('#cafe').classList.add('routing');phone(`<div class="success-icon">✓</div><h3 style="text-align:center">You’re all set.</h3><p style="text-align:center">${online?'Demo payment approved.':'Pay at the counter when you’re ready.'}<br>Your order is with the kitchen.</p><div class="order-steps"><span class="done"><b>✓</b>Received</span><span><b>♨</b>Preparing</span><span><b>♡</b>Enjoy</span></div><button class="primary" data-action="kitchen">Follow your order <span>↗</span></button><div class="phone-badge">Simulated order · Table ${table}</div>`);notify(`Table ${table} → Kitchen. Order received!`)}
function renderKitchen(){const items=order?order.items:[0,3],status=order?.status||'preview';phone(`<div class="tiny-label">THE HEART OF THE CAFÉ</div><h3>${status==='served'?'Another happy table.':'In good hands.'}</h3><p>${order?'Your live demo order.':'A sample ticket. Try ordering to send your own.'}</p><div class="kitchen-ticket"><div class="ticket-top"><span>TABLE ${order?.table||'04'}</span><small>${status==='preview'?'SAMPLE':status.toUpperCase()}</small></div>${[...new Set(items)].map(i=>`<div class="ticket-item">${items.filter(v=>v===i).length} × ${products[i].name}</div>`).join('')}<div class="ticket-meta">⌁ ${order?.paid?'Demo payment complete':'Pay at counter'} · Dine in</div></div><div class="order-steps"><span class="done"><b>✓</b>Received</span><span class="${['preparing','ready','served'].includes(status)?'done':''}"><b>♨</b>Preparing</span><span class="${['ready','served'].includes(status)?'done':''}"><b>✓</b>Ready</span></div><button class="primary" data-action="advance">${status==='preview'?'Try a sample order':status==='received'?'Start preparing':status==='preparing'?'Ready for the table':status==='ready'?'Mark as served':'See the big picture'} <span>↗</span></button>`)}
function advance(){if(!order)order={items:[0,3],table:'04',status:'received',total:320,paid:false};else if(order.status==='received')order.status='preparing';else if(order.status==='preparing'){order.status='ready';notify(`Table ${order.table}, your order is ready!`)}else if(order.status==='ready'){order.status='served';notify('Served with a little extra happiness.')}else{setScene(4);return}renderKitchen()}
function renderTour(){phone(`<div class="tiny-label">A FEEL FOR THE PLACE</div><h3>${tourView==='cafe'?'Your new happy place.':'A little behind the scenes.'}</h3><div class="tour-mini"><svg viewBox="0 0 210 130" aria-label="Illustrated ${tourView} preview">${tourView==='cafe'?`<rect width="210" height="130" fill="#d5d4bd"/><path d="M0 95L210 87V130H0" fill="#a98960"/><path d="M20 14H95V86H20Z" fill="#6c8872" stroke="#f1e9d1" stroke-width="5"/><path d="M57 15v70M21 49h72" stroke="#e9e4cc" stroke-width="4"/><ellipse cx="131" cy="95" rx="43" ry="13" fill="#d8b784"/><path d="M130 97v32" stroke="#52603d" stroke-width="7"/><path d="M160 0v30" stroke="#635f44"/><path d="M139 37q20-28 42 0Z" fill="#c68d45"/><path d="M33 127l-4-31h20l-4 31" fill="#b5794d"/><path d="M38 96V65m0 19-12-13m12 8 13-17" stroke="#405e38" stroke-width="5"/>`:`<rect width="210" height="130" fill="#cbd1bd"/><path d="M0 95H210V130H0" fill="#6b7e64"/><path d="M14 59h180v35H14" fill="#f0ecda"/><rect x="27" y="32" width="60" height="27" fill="#445d46"/><path d="M120 45q-7-24 9-25t15 25" fill="#fff9e6"/><circle cx="132" cy="48" r="10" fill="#bc8d66"/><path d="M118 58h28l8 32h-42Z" fill="#eee9d6"/><path d="M164 59q-5-15 0-20t0-15" fill="none" stroke="#f9f7e6" stroke-width="3"/>`}</svg></div><div class="view-toggle"><button data-view="cafe" class="${tourView==='cafe'?'active':''}">◎ Café floor</button><button data-view="kitchen" class="${tourView==='kitchen'?'active':''}">♨ Open kitchen</button></div><p>An illustrated walkthrough concept. A real venue can add its own 360° photography.</p><div class="tour-label"><i class="live-dot"></i> ${tourView==='cafe'?'Find your favourite corner':'See where the magic happens'}</div><button class="primary" data-action="reserve">Save a seat <span>↗</span></button>`);$('#cafe').classList.toggle('kitchen-view',tourView==='kitchen')}
function renderDashboard(){const served=order?.status==='served';phone(`<div class="tiny-label">A GOOD DAY, AT A GLANCE</div><h3>Hello, big picture.</h3><p>Illustrative café data + your demo order.</p><div class="metric-grid"><div class="metric"><small>TODAY’S SALES</small><b>${currency(6840+(served?order.total:0))}</b></div><div class="metric"><small>ORDERS</small><b>${24+(order?1:0)}</b></div><div class="metric"><small>TABLES BUSY</small><b>${order&&!served?'5':'4'}<span style="font-size:11px;color:#8f9b7e"> / 8</span></b></div><div class="metric"><small>IN THE KITCHEN</small><b>${3+(order&&!served?1:0)}</b></div></div><div class="tiny-label" style="margin:13px 0 8px">THE DAILY RHYTHM</div><div class="chart">${[25,43,65,96,68,49,74].map(h=>`<span style="height:${h}%"></span>`).join('')}</div><div class="chart-label"><span>9 AM</span><span>12 PM</span><span>3 PM</span></div><div class="phone-badge">Sample figures · Not business forecasts</div>`)}
function showExtra(type){const d=$('#extra-dialog');if(type==='staff')$('#extra-content').innerHTML=`<div class="dialog-symbol">♧</div><h2>A hand, in one tap.</h2><p>No waving across the room. Send a little nudge from table ${table}.</p><label>What would you like?<select id="help-kind"><option>A member of staff</option>A water refill</option>The bill, please</option>Help with an allergy question</option></select></label><button class="primary" data-action="call-staff">Call for a hand <span>↗</span></button>`;if(type==='loyalty')$('#extra-content').innerHTML=`<div class="dialog-symbol">✳</div><h2>Good coffee. Good karma.</h2><p>Four visits. One little thank-you waiting.</p><div class="stamp-row">✳ ✳ ✳ ✳ <span class="empty">✳</span></div><button class="primary" data-action="stamp">Try your fifth stamp <span>+</span></button><p>Illustrative rewards programme.</p>`;if(type==='reserve')$('#extra-content').innerHTML=`<div class="dialog-symbol">◎</div><h2>Your corner is waiting.</h2><p>Try a table reservation for this demo café.</p><label>Your party<select id="party"><option>2 guests</option>3 guests</option>4 guests</option>6 guests</option></select></label><label>Today’s available times<select id="slot"><option>6:00 PM</option><option>7:30 PM</option><option>8:30 PM</option></select></label><button class="primary" data-action="book">Save my seat <span>↗</span></button><p>Simulation only. No real reservation is made.</p>`;d.showModal()}
function stopTour(){clearInterval(tourTimer);tourTimer=null;$('#auto-tour').textContent='▷ Watch the story'}
function startTour(){if(tourTimer){stopTour();return}setScene(0);$('#auto-tour').textContent='Ⅱ Pause the story';tourTimer=setInterval(()=>{if(scene===4){stopTour();return}setScene(scene+1)},5500)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.scene!==undefined){stopTour();setScene(+b.dataset.scene)}if(b.dataset.table){stopTour();table=b.dataset.table;setScene(0);notify(`Welcome to table ${table}.`)}if(b.dataset.category){menuCategory=b.dataset.category;renderMenu()}if(b.dataset.add!==undefined){if(cart.length>=9){notify('Demo orders support up to 9 items.');return}cart.push(+b.dataset.add);renderMenu()}if(b.dataset.remove!==undefined){cart.splice(cart.indexOf(+b.dataset.remove),1);cart.length?renderCart():renderMenu()}if(b.dataset.view){tourView=b.dataset.view;renderTour()}if(b.dataset.extra)showExtra(b.dataset.extra);const a=b.dataset.action;if(a==='scan'){stopTour();setScene(1)}if(a==='cart')renderCart();if(a==='back-menu')renderMenu();if(a==='order')placeOrder();if(a==='kitchen')setScene(2);if(a==='advance')advance();if(a==='reserve')showExtra('reserve');if(a==='call-staff'){$('#extra-content').innerHTML=`<div class="success-icon">✓</div><h2>On our way.</h2><p>Demo request sent from table ${table}: ${$('#help-kind').value}.</p><button class="primary" data-action="close">Lovely, thank you <span>✓</span></button>`;notify('Staff notified · Demo request')}if(a==='stamp'){$('.stamp-row').innerHTML='✳ ✳ ✳ ✳ ✳';b.textContent='Your next coffee is on us ✓';b.disabled=true;notify('Reward unlocked! Your demo card is full.')}if(a==='book'){$('#extra-content').innerHTML=`<div class="success-icon">✓</div><h2>See you soon.</h2><p>Demo reservation: ${$('#party').value} · Today at ${$('#slot').value}.<br>Your table is saved in this preview only.</p><button class="primary" data-action="close">Sounds good <span>✓</span></button>`}if(a==='close'||b.classList.contains('dialog-close'))$('#extra-dialog').close()});
$('#kitchen-hotspot').onclick=()=>{stopTour();setScene(2)};$('#auto-tour').onclick=startTour;$('#tour-top').onclick=()=>{$('#playground').scrollIntoView({behavior:'smooth'});if(!tourTimer)startTour()};$('#restart').onclick=()=>{stopTour();order=null;cart=[];table='04';setScene(0);$('#playground').scrollIntoView({behavior:'smooth'})};$('#extra-dialog').addEventListener('click',e=>{if(e.target===$('#extra-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#sound').onclick=async()=>{try{if(!audioContext){audioContext=new(window.AudioContext||window.webkitAudioContext)();const buffer=audioContext.createBuffer(1,audioContext.sampleRate*3,audioContext.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){last=(last+Math.random()*.02-.01)*.99;data[i]=last}ambient=audioContext.createBufferSource();ambient.buffer=buffer;ambient.loop=true;const gain=audioContext.createGain();gain.gain.value=.12;ambient.connect(gain);gain.connect(audioContext.destination);ambient.start()}soundOn=!soundOn;await audioContext[soundOn?'resume':'suspend']();$('#sound span').textContent=soundOn?'Sound on':'Sound off';$('#sound').setAttribute('aria-label',`Turn ambient sound ${soundOn?'off':'on'}`)}catch{notify('Ambient sound is unavailable in this browser.')}};
$$('[role=tab]').forEach((tab,i)=>tab.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const n=(i+(e.key==='ArrowRight'?1:4))%5;stopTour();setScene(n);$$('[role=tab]')[n].focus()}}));
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopTour();if(audioContext&&soundOn){audioContext.suspend();soundOn=false;$('#sound span').textContent='Sound off'}}});
tables();setScene(0);
